import type { Config } from "./config.ts";
import type { Db } from "./db/client.ts";

// Hono's generic for every router and handler: `Env` is the Bindings type
// generated by `pnpm cf-typegen` (worker-configuration.d.ts).
export type AppEnv = {
  Bindings: Env;
  Variables: {
    config: Config;
    db: Db;
  };
};
